arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1990_06.json', 'r') as f:
    data = json.load(f)

doc = data['document']
# Find pages with tables
for i, page in enumerate(doc.get('pages', [])):
    if isinstance(page, dict):
        if 'tables' in page:
            print(f'Page {i} has tables')
            for j, table in enumerate(page.get('tables', [])[:2]):
                print(f'  Table {j}:', type(table))
                if isinstance(table, dict):
                    print(f'  Table keys: {list(table.keys())[:5]}')
"
